//! Renders the n4yk0 cat-skull as truecolor half-block pixel art, with a "decrypt" reveal animation.

use std::fmt::Write as _;
use std::io::{self, IsTerminal, Write};
use std::sync::LazyLock;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

/// Generated by `cargo run --example logogen`; do not edit by hand.
const GRID: &str = include_str!("grid.txt");

const PIXEL_EMPTY: char = '.';
const PIXEL_OUTLINE: char = 'K';
const PIXEL_WHITE: char = 'W';
const PIXEL_SHADE: char = 'L';
const PIXEL_BLUE: char = 'B';
const PIXEL_GLOW: char = 'G';

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Rgb(u8, u8, u8);

const NEON: Rgb = Rgb(0x00, 0xFF, 0x9C);

fn palette(pixel: char) -> Option<Rgb> {
    match pixel {
        PIXEL_OUTLINE => Some(NEON),
        PIXEL_GLOW => Some(Rgb(0x0B, 0x3D, 0x2E)),
        PIXEL_WHITE => Some(Rgb(0xEE, 0xF3, 0xFA)),
        PIXEL_SHADE => Some(Rgb(0xA9, 0xBE, 0xE6)),
        PIXEL_BLUE => Some(Rgb(0x3D, 0x63, 0xB8)),
        _ => None,
    }
}

const RESET: &str = "\x1b[0m";
const FAINT: &str = "\x1b[2m";
const GLITCH_GLYPHS: &[u8] = b"01<>/\\|#$%&*+=?!";
const DEFAULT_FRAMES: usize = 16;
const DEFAULT_INTERVAL: Duration = Duration::from_millis(35);
const DEFAULT_GAP: usize = 3;

#[derive(Clone, Debug, Default)]
pub struct Options {
    /// Lines shown beside the logo (vertically centred), or under it when `below` is set.
    pub side: Vec<String>,
    pub below: bool,
    /// Columns between logo and side text; 0 means 3.
    pub gap: usize,
    pub indent: usize,
    /// 24-bit ANSI colours; without it the logo is a plain block silhouette.
    pub color: bool,
    /// Zero values mean 16 frames, 35ms apart.
    pub frames: usize,
    pub interval: Duration,
    /// Makes the glitch noise reproducible; 0 picks a time-based seed.
    pub seed: u64,
}

impl Options {
    fn with_defaults(&self) -> Options {
        let mut o = self.clone();
        if o.gap == 0 {
            o.gap = DEFAULT_GAP;
        }
        if o.frames == 0 {
            o.frames = DEFAULT_FRAMES;
        }
        if o.interval.is_zero() {
            o.interval = DEFAULT_INTERVAL;
        }
        if o.seed == 0 {
            o.seed = SystemTime::now().duration_since(UNIX_EPOCH).map_or(1, |d| d.as_nanos() as u64 | 1);
        }
        o
    }
}

/// Whether a stream should get colours and animation: a terminal that is not "dumb", honouring NO_COLOR (no-color.org).
pub fn detect(stream: &impl IsTerminal) -> (bool, bool) {
    detect_with(stream.is_terminal(), std::env::var("TERM").ok().as_deref(), std::env::var("NO_COLOR").ok().as_deref())
}

fn detect_with(is_terminal: bool, term: Option<&str>, no_color: Option<&str>) -> (bool, bool) {
    let tty = is_terminal && term != Some("dumb");
    (tty && no_color.is_none_or(str::is_empty), tty)
}

static PIXELS: LazyLock<Grid> = LazyLock::new(|| Grid::parse(GRID).with_glow());

pub fn width() -> usize {
    PIXELS.width()
}

pub fn height() -> usize {
    PIXELS.rows.len() / 2
}

pub fn lines(color: bool) -> Vec<String> {
    PIXELS.render(color)
}

pub fn print(w: &mut dyn Write, opts: &Options) -> io::Result<()> {
    let opts = opts.with_defaults();
    w.write_all(frame(&compose(&lines(opts.color), &opts), false).as_bytes())?;
    w.flush()
}

/// Draws noisy frames that converge on the logo, rewriting them in place, then leaves the final frame on screen.
pub fn animate(w: &mut dyn Write, opts: &Options) -> io::Result<()> {
    let opts = opts.with_defaults();
    let mut rng = SplitMix64(opts.seed);
    let hidden_side = Options { side: vec![String::new(); opts.side.len()], ..opts.clone() };
    for f in 0..opts.frames {
        let noisy = PIXELS.render_glitch(f as f64 / opts.frames as f64, &mut rng, opts.color);
        w.write_all(frame(&compose(&noisy, &hidden_side), f > 0).as_bytes())?;
        w.flush()?;
        thread::sleep(opts.interval);
    }
    w.write_all(frame(&compose(&PIXELS.render(opts.color), &opts), true).as_bytes())?;
    w.flush()
}

fn frame(lines: &[String], rewind: bool) -> String {
    let mut b = String::new();
    if rewind && !lines.is_empty() {
        let _ = write!(b, "\x1b[{}A", lines.len());
    }
    for l in lines {
        if rewind {
            b.push_str("\r\x1b[2K");
        }
        b.push_str(l);
        b.push('\n');
    }
    b
}

/// Relies on every logo line being exactly `width()` columns wide, so side text may carry any ANSI styling.
fn compose(logo: &[String], opts: &Options) -> Vec<String> {
    let pad = " ".repeat(opts.indent);
    if opts.below || opts.side.is_empty() {
        let mut out: Vec<String> = logo.iter().map(|l| format!("{pad}{l}").trim_end_matches(' ').to_string()).collect();
        if !opts.side.is_empty() {
            out.push(String::new());
            out.extend(opts.side.iter().map(|s| format!("{pad}{s}").trim_end_matches(' ').to_string()));
        }
        return out;
    }
    let height = logo.len().max(opts.side.len());
    let top = (height - opts.side.len()) / 2;
    let blank = " ".repeat(width());
    let gap = " ".repeat(opts.gap);
    (0..height)
        .map(|i| {
            let left = logo.get(i).map_or(blank.as_str(), String::as_str);
            let right = i.checked_sub(top).and_then(|j| opts.side.get(j)).map_or("", String::as_str);
            format!("{pad}{left}{gap}{right}").trim_end_matches(' ').to_string()
        })
        .collect()
}

struct Grid {
    rows: Vec<Vec<char>>,
}

impl Grid {
    fn parse(raw: &str) -> Grid {
        let mut rows: Vec<Vec<char>> = raw.trim_matches('\n').split('\n').map(|l| l.chars().collect()).collect();
        if rows.len() % 2 == 1 {
            let width = rows[0].len();
            rows.push(vec![PIXEL_EMPTY; width]);
        }
        Grid { rows }
    }

    /// Keeps outline pixels touching another colour neon and dims solid interiors,
    /// otherwise the black ears and eyes of the original render as flat neon blobs.
    fn with_glow(&self) -> Grid {
        let mut rows = self.rows.clone();
        for (y, row) in self.rows.iter().enumerate() {
            for (x, &p) in row.iter().enumerate() {
                if p == PIXEL_OUTLINE && !self.touches_other(x as isize, y as isize) {
                    rows[y][x] = PIXEL_GLOW;
                }
            }
        }
        Grid { rows }
    }

    fn at(&self, x: isize, y: isize) -> char {
        if x < 0 || y < 0 {
            return PIXEL_EMPTY;
        }
        self.rows.get(y as usize).and_then(|row| row.get(x as usize)).copied().unwrap_or(PIXEL_EMPTY)
    }

    fn touches_other(&self, x: isize, y: isize) -> bool {
        [(1, 0), (-1, 0), (0, 1), (0, -1)].iter().any(|(dx, dy)| self.at(x + dx, y + dy) != PIXEL_OUTLINE)
    }

    fn width(&self) -> usize {
        self.rows.first().map_or(0, Vec::len)
    }

    /// Packs two pixel rows per terminal line with half blocks.
    fn render(&self, color: bool) -> Vec<String> {
        self.cells().map(|row| row.into_iter().map(|(top, bottom)| half_block(top, bottom, color)).collect()).collect()
    }

    /// Shows each opaque cell with probability `progress`; hidden cells show neon noise.
    fn render_glitch(&self, progress: f64, rng: &mut SplitMix64, color: bool) -> Vec<String> {
        self.cells()
            .map(|row| {
                let mut b = String::new();
                for (top, bottom) in row {
                    if top == PIXEL_EMPTY && bottom == PIXEL_EMPTY {
                        b.push(' ');
                    } else if rng.float() < progress {
                        b.push_str(&half_block(top, bottom, color));
                    } else {
                        let glyph = GLITCH_GLYPHS[rng.below(GLITCH_GLYPHS.len())] as char;
                        if color {
                            let _ = write!(b, "{FAINT}{}{glyph}{RESET}", fg(NEON));
                        } else {
                            b.push(glyph);
                        }
                    }
                }
                b
            })
            .collect()
    }

    fn cells(&self) -> impl Iterator<Item = Vec<(char, char)>> + '_ {
        (0..self.rows.len() / 2).map(move |line| {
            let y = (line * 2) as isize;
            (0..self.width() as isize).map(|x| (self.at(x, y), self.at(x, y + 1))).collect()
        })
    }
}

fn half_block(top: char, bottom: char, color: bool) -> String {
    match (palette(top), palette(bottom), color) {
        (Some(t), Some(b), true) => format!("{}{}▀{RESET}", fg(t), bg(b)),
        (Some(_), Some(_), false) => "█".to_string(),
        (Some(t), None, true) => format!("{}▀{RESET}", fg(t)),
        (Some(_), None, false) => "▀".to_string(),
        (None, Some(b), true) => format!("{}▄{RESET}", fg(b)),
        (None, Some(_), false) => "▄".to_string(),
        (None, None, _) => " ".to_string(),
    }
}

fn fg(c: Rgb) -> String {
    format!("\x1b[38;2;{};{};{}m", c.0, c.1, c.2)
}

fn bg(c: Rgb) -> String {
    format!("\x1b[48;2;{};{};{}m", c.0, c.1, c.2)
}

/// Tiny deterministic generator for the glitch noise (splitmix64, public domain reference by S. Vigna).
struct SplitMix64(u64);

impl SplitMix64 {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    fn float(&mut self) -> f64 {
        (self.next() >> 11) as f64 / (1u64 << 53) as f64
    }

    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

#[cfg(test)]
mod tests {
    use std::sync::LazyLock;

    use regex::Regex;

    use super::*;

    static ANSI: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"\x1b\[[0-9;]*[A-Za-z]").unwrap());

    fn visible_width(s: &str) -> usize {
        ANSI.replace_all(s, "").chars().count()
    }

    #[test]
    fn grid_shape_and_palette() {
        let g = Grid::parse(GRID);
        assert!(!g.rows.is_empty() && g.rows.len().is_multiple_of(2));
        for (i, row) in g.rows.iter().enumerate() {
            assert_eq!(row.len(), g.width(), "row {i}");
            assert!(row.iter().all(|&p| p == PIXEL_EMPTY || palette(p).is_some()), "row {i}");
        }
        assert_eq!((width(), height()), (30, 18));
    }

    #[test]
    fn lines_have_fixed_visible_width() {
        for color in [true, false] {
            let lines = lines(color);
            assert_eq!(lines.len(), height());
            for l in &lines {
                assert_eq!(visible_width(l), width(), "color={color}: {l:?}");
                assert!(color || !l.contains('\x1b'), "plain mode must not emit escapes");
            }
        }
        assert!(lines(true).concat().contains("\x1b[38;2;0;255;156m"));
    }

    #[test]
    fn parse_pads_odd_height() {
        let g = Grid::parse("\nK.\n.K\nKK\n");
        assert_eq!(g.rows.len(), 4);
        assert_eq!(g.rows[3], ['.', '.']);
    }

    #[test]
    fn glow_dims_interior_only() {
        let g = Grid::parse("KKK\nKKK\nKKK\n.W.\n").with_glow();
        assert_eq!(g.rows[1][1], PIXEL_GLOW);
        assert_eq!((g.rows[0][0], g.rows[2][1]), (PIXEL_OUTLINE, PIXEL_OUTLINE));
    }

    #[test]
    fn half_blocks() {
        for (top, bottom, plain) in [
            (PIXEL_EMPTY, PIXEL_EMPTY, " "),
            (PIXEL_WHITE, PIXEL_EMPTY, "▀"),
            (PIXEL_EMPTY, PIXEL_BLUE, "▄"),
            (PIXEL_WHITE, PIXEL_BLUE, "█"),
        ] {
            assert_eq!(half_block(top, bottom, false), plain);
            assert_eq!(visible_width(&half_block(top, bottom, true)), 1);
        }
        assert!(half_block(PIXEL_WHITE, PIXEL_BLUE, true).contains("\x1b[48;2;61;99;184m"));
    }

    fn side(lines: &[&str]) -> Vec<String> {
        lines.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn compose_side_by_side_centres_text() {
        let logo = side(&["AA", "BB", "CC", "DD"]);
        let lines = compose(&logo, &Options { side: side(&["x", "y"]), gap: 2, indent: 1, ..Options::default() });
        assert_eq!(lines, [" AA", " BB  x", " CC  y", " DD"]);
    }

    #[test]
    fn compose_tall_side_and_below() {
        let tall = compose(&side(&["AA"]), &Options { side: side(&["1", "2", "3"]), gap: 1, ..Options::default() });
        assert_eq!(tall.len(), 3);
        assert!(tall[2].ends_with(" 3") && tall[1].trim() == "2", "{tall:?}");
        let below = compose(
            &side(&["AA", "BB"]),
            &Options { side: side(&["x"]), below: true, indent: 2, ..Options::default() },
        );
        assert_eq!(below.join("|"), "  AA|  BB||  x");
        assert_eq!(compose(&side(&["AA"]), &Options::default()), ["AA"]);
    }

    #[test]
    fn print_is_static_and_plain_without_color() {
        let mut out = Vec::new();
        print(&mut out, &Options { side: side(&["hello"]), indent: 1, ..Options::default() }).unwrap();
        let s = String::from_utf8(out).unwrap();
        assert_eq!(s.trim_end_matches('\n').split('\n').count(), height());
        assert!(s.contains("hello") && !s.contains('\x1b'));
    }

    #[test]
    fn animate_rewrites_in_place_and_ends_on_final_frame() {
        let opts = Options {
            side: side(&["hello"]),
            frames: 3,
            interval: Duration::from_micros(1),
            seed: 42,
            ..Options::default()
        };
        let mut out = Vec::new();
        animate(&mut out, &opts).unwrap();
        let s = String::from_utf8(out).unwrap();
        let rewind = format!("\x1b[{}A", height());
        assert_eq!(s.matches(&rewind).count(), 3, "frames 2, 3 and the final one rewind");
        let final_frame = &s[s.rfind(&rewind).unwrap() + rewind.len()..];
        let mut printed = Vec::new();
        print(&mut printed, &opts).unwrap();
        assert_eq!(final_frame.replace("\r\x1b[2K", ""), String::from_utf8(printed).unwrap());
        assert!(!s[..s.find(&rewind).unwrap()].contains("hello"), "side text stays hidden until the final frame");
    }

    #[test]
    fn animate_is_reproducible_with_seed() {
        let render = || {
            let mut out = Vec::new();
            let opts =
                Options { frames: 4, interval: Duration::from_micros(1), seed: 7, color: true, ..Options::default() };
            animate(&mut out, &opts).unwrap();
            out
        };
        assert_eq!(render(), render());
    }

    struct Failing;

    impl Write for Failing {
        fn write(&mut self, _: &[u8]) -> io::Result<usize> {
            Err(io::Error::other("closed"))
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    #[test]
    fn write_errors_propagate() {
        assert!(print(&mut Failing, &Options::default()).is_err());
        assert!(
            animate(&mut Failing, &Options { frames: 1, interval: Duration::from_micros(1), ..Options::default() })
                .is_err()
        );
    }

    #[test]
    fn detect_honours_dumb_terminals_and_no_color() {
        assert_eq!(detect_with(true, Some("xterm-256color"), None), (true, true));
        assert_eq!(detect_with(true, Some("xterm-256color"), Some("")), (true, true));
        assert_eq!(detect_with(true, Some("xterm-256color"), Some("1")), (false, true));
        assert_eq!(detect_with(true, Some("dumb"), None), (false, false));
        assert_eq!(detect_with(false, None, None), (false, false));
        let file = tempfile::tempfile().unwrap();
        assert_eq!(detect(&file), (false, false));
    }
}
